const msg = $json.message || {};
const from = msg.from || {};
const text = String(msg.text || '').trim();

if (!text.startsWith('/start')) {
  return [{ json: { ok: false, reason: 'not /start command' } }];
}

const chatId = String(msg.chat.id);
const username = String(from.username || '');
const firstName = String(from.first_name || 'Usuario');
const userId = String(from.id || '');

if (!chatId || !username) {
  return [{ json: { ok: false, reason: 'missing chat_id or username', chat: chatId, user: username } }];
}

return [{ json: {
  ok: true,
  chat_id: chatId,
  username: username.toLowerCase(),
  first_name: firstName,
  user_id: userId,
  timestamp: new Date().toISOString()
} }];

const res = $input.first().json || {};
return [{ json: {
  ok: true,
  message: 'Chat ID registrado correctamente',
  chat_id: $('Extraer /start').first().json.chat_id,
  username: $('Extraer /start').first().json.username,
  status: res.status || 200
} }];
